const results: any[] = [];
for (const f of files) {
  const content = await tools.readFile({ path: f });
  const lines = content.split(/\r?\n/).filter((l) => l.trim().length > 0);
  // 每行一个条目；按任务描述每个文件生成一个 meta.json，取每行条目（若多行则取最后一行有意义条目）
  // 根据实际数据每个文件只有一行，这里处理第一行
  const [name, scoreStr] = lines[0].split(",");
  const score = Number(scoreStr.trim());
  const meta = { name: name.trim(), score, passed: score >= 60 };
  const outPath = f.replace(/\.txt$/, ".meta.json");
  await tools.writeFile({ path: outPath, content: JSON.stringify(meta) });
  results.push({ outPath, meta });
}
console.log(JSON.stringify(results, null, 2));"}

